function validate([points]) {
  if (points.length < 1 || points.length > 500) return 'points needs 1 to 500 points.';
  const seen = new Set();
  for (const point of points) {
    if (point.length !== 2) return 'Each point is a pair [x, y].';
    if (point.some(v => v < -10000 || v > 10000)) return 'Coordinates are between -10^4 and 10^4.';
    const key = point[0] + ',' + point[1];
    if (seen.has(key)) return 'All points must be distinct.';
    seen.add(key);
  }
  return null;
}

