function numberOfBoomerangs(points) {
  let total = 0;
  for (const [x, y] of points) {
    const count = new Map();
    for (const [px, py] of points) {
      const dx = x - px;
      const dy = y - py;
      const distance = dx * dx + dy * dy;
      count.set(distance, (count.get(distance) ?? 0) + 1);
    }
    for (const same of count.values()) {
      total += same * (same - 1);
    }
  }
  return total;
}

