function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  // Small inputs use a tight grid so equal distances are common; large ones mix a tight and a wide spread.
  const n = size === 'large' ? 500 : 1 + pick(9);
  const span = size === 'large' ? (rand() < 0.5 ? 30 : 10000) : (rand() < 0.8 ? 2 + pick(3) : 10000);
  const seen = new Set();
  const points = [];
  while (points.length < n) {
    const point = [pick(2 * span + 1) - span, pick(2 * span + 1) - span];
    const key = point[0] + ',' + point[1];
    if (seen.has(key)) continue;
    seen.add(key);
    points.push(point);
  }
  return [points];
}
